  function uiAction(action,p){
    switch(action){
    case'quests':ui.questsOpen=!ui.questsOpen;break;
    case'liveTab':ui.liveTab=p.tab==='music'?'music':'festival';dirty=true;break;
      case'musicPrevious':stepMusic(-1);break;
      case'musicNext':stepMusic(1);break;
      case'musicToggle':toggleMusic();break;
      case'mode':ui.mode=p.challenge;break;
      case'settings':openMenu('settings');break;
      case'close':closeMenu();break;
      case'service':if(g.playing&&!g.pour&&(!g.paused||ui.menu==='service')){if(g._inputGuard>0)ui.pendingService=true;else openMenu('service');}break;
      case'fullscreen':document.getElementById('fullscreen-button')?.click();break;
      case'holdPause':closeMenu(false);run('pause',{reason:'manual'});break;
      case'staff':ui.opPage=0;if(g.playing||g.phase==='planning')openMenu('operations');break;
      case'upgrades':ui.opPage=1;if(g.playing||g.phase==='planning')openMenu('operations');break;
      case'events':ui.opPage=2;if(g.playing||g.phase==='planning')openMenu('operations');break;
      case'guests':ui.opPage=3;if(g.playing||g.phase==='planning')openMenu('operations');break;
      case'opPage':ui.opPage=p.index;ui.visualPreview=null;break;
      case'visualPreview':ui.visualPreview={type:p.type,index:p.index,level:p.level};break;
      case'previewBack':ui.visualPreview=null;break;
      case'language':run('language',{language:g.language==='en'?'ko':'en'});break;
      case'deskFocus':dayDesk.focus(p.channel);break;
      case'floor':if(ui.menu)closeMenu();if(!g.paused)ui.floorOpen=!ui.floorOpen;break;
      case'floorClose':ui.floorOpen=false;break;
    }
    dirty=true;
  }
  function handleAction(action,p={}){if(orientationBlocked&&action!=='ui:fullscreen')return;if(action.startsWith('ui:'))uiAction(action.slice(3),p);else{if(action==='deskWork')dayDesk.focus(p.task===1?'phone':'monitor');if(['menuItem','prepare'].includes(action)&&ui.menu==='service')closeMenu();if(['lobby','next','retry','start','continue','resume'].includes(action))ui.menu=null;const result=run(action,p);if(action==='menuItem'&&!result.success&&result.code==='wrong_item')ui.pendingService=true;if(action==='playlist'&&allowedTracks().includes(p.index)){run('musicState',{paused:false});music.select();}}wakeAudio();}
