  await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));

  const result={g,world,canvas,albumArt,root:host,get orientationBlocked(){return orientationBlocked;},destroy(){stopped=true;cancelAnimationFrame(raf);observer.disconnect();host.removeEventListener('click',clickHandler);host.removeEventListener('change',changeHandler);document.removeEventListener('keydown',keyHandler);window.removeEventListener('blur',blurHandler);music.destroy();albumArt.destroy();g.save();world.destroy?.();host.remove();}};
  window.simbarGame=g;
